[{"order":1,"type":"heading","text":"Handling Keyboard, Mouse, and Touch Gestures in Playwright"},{"order":2,"type":"paragraph","text":"Automating modern web applications often requires simulating complex user interactions. Playwright provides a robust and high-level API to handle keyboard inputs, precise mouse movements, and mobile touch gestures seamlessly."},{"order":3,"type":"subheading","text":"Keyboard Interactions"},{"order":4,"type":"paragraph","text":"Playwright allows you to type text, press individual keys, and manage modifier keys like Shift, Control, or Alt. You can target specific elements or send global keystrokes."},{"order":5,"type":"code","text":"const { test } = require('@playwright/test');

test('keyboard input example', async ({ page }) => {
  await page.goto('https://example.com/login');

  // Type into an input field
  await page.fill('#username', 'my_user');

  // Press specific keys with modifiers
  await page.press('#username', 'Tab');

  // Simulating typing with delays
  await page.type('#password', 'secretPassword', { delay: 100 });

  // Pressing Enter to submit
  await page.press('#password', 'Enter');
});"},{"order":6,"type":"subheading","text":"Mouse Actions"},{"order":7,"type":"paragraph","text":"For scenarios requiring more than a standard click, Playwright's mouse API provides fine-grained control over hover states, double clicks, right clicks, and drag-and-drop operations."},{"order":8,"type":"code","text":"test('advanced mouse interactions', async ({ page }) => {
  await page.goto('https://example.com/dashboard');

  // Hover over an element to reveal a menu
  await page.hover('.menu-item');

  // Right-click (context menu)
  await page.click('.context-target', { button: 'right' });

  // Drag and Drop
  await page.dragAndDrop('#source', '#target');
});"},{"order":9,"type":"subheading","text":"Touch Gestures"},{"order":10,"type":"paragraph","text":"When testing mobile web applications or responsive layouts, simulating touch events is crucial. Playwright supports touch interactions natively when configured with a mobile viewport or device descriptor."},{"order":11,"type":"code","text":"const { devices } = require('@playwright/test');

test.use({ ...devices['iPhone 13'] });

test('touch gestures example', async ({ page }) => {
  await page.goto('https://example.com/mobile');

  // Tap an element
  await page.tap('.mobile-button');

  // Simulating a swipe gesture using mouse down, move, and up
  await page.mouse.move(100, 300);
  await page.mouse.down();
  await page.mouse.move(300, 300, { steps: 5 });
  await page.mouse.up();
});"},{"order":12,"type":"subheading","text":"Best Practices"},{"order":13,"type":"bullet_point","text":"Prefer semantic actions like page.click() and page.fill() over low-level mouse and keyboard events whenever possible."},{"order":14,"type":"bullet_point","text":"Use the delay option in typing when dealing with applications that have aggressive autocomplete or input masking."},{"order":15,"type":"bullet_point","text":"Always emulate a mobile device context when testing touch gestures to ensure accurate event dispatching."}]
